<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { CheckCircle2, Clock3, RefreshCw, ShieldCheck, Terminal, XCircle } from 'lucide-vue-next'
import { listCredentials, type Credential } from '@/api/cmdb'
import { useAuthStore } from '@/stores/useAuthStore'

type Operation={id:string;name:string;description:string;command:string;risk:string}
type RemoteAsset={id:string;name:string;ip:string;status:string;projectGroup:string;environment:string;tags:string[]}
type TargetOptions={projectGroups:string[];tags:string[]}
type TargetResolve={targets:string[];assets:RemoteAsset[]}
type TargetResult={target:string;status:string;output?:string;error?:string;duration?:string}
type Execution={id:string;operationId:string;operationName:string;command:string;risk:string;targets:string[];port:number;status:string;requestedBy:string;approvedBy?:string;createdAt:string;finishedAt?:string;results:TargetResult[]}
const auth=useAuthStore(),operations=ref<Operation[]>([]),executions=ref<Execution[]>([]),credentials=ref<Credential[]>([]),targetOptions=ref<TargetOptions>({projectGroups:[],tags:[]}),operationId=ref('uptime'),commandMode=ref<'preset'|'custom'>('preset'),customCommand=ref(''),targetMode=ref<'projectGroup'|'tag'|'ip'>('projectGroup'),selectedGroups=ref<string[]>([]),selectedTags=ref<string[]>([]),ipText=ref(''),resolvedTargets=ref<string[]>([]),resolvedAssets=ref<RemoteAsset[]>([]),port=ref(22),credentialId=ref(''),busy=ref(false),resolving=ref(false),error=ref(''),message=ref('')
const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}))
const sshCredentials=computed(()=>credentials.value.filter(item=>item.kind==='ssh'))
const activeOperation=computed(()=>operations.value.find(item=>item.id===operationId.value))
async function request<T>(url:string,options?:RequestInit){const response=await fetch(url,{...options,headers:headers.value});if(!response.ok){let detail=`请求失败 (${response.status})`;try{const body=await response.json() as {message?:string};detail=body.message||detail}catch{}throw new Error(detail)}return response.json() as Promise<T>}
async function load(){try{const [ops,history,creds,options]=await Promise.all([request<Operation[]>('/api/v1/discovery/remote-operations'),request<Execution[]>('/api/v1/discovery/remote-executions'),listCredentials(auth.token),request<TargetOptions>('/api/v1/discovery/remote-target-options')]);operations.value=ops;executions.value=history;credentials.value=creds;targetOptions.value=options;error.value=''}catch(reason){error.value=reason instanceof Error?reason.message:'远程执行数据加载失败'}}
function selectorPayload(){return {projectGroups:targetMode.value==='projectGroup'?selectedGroups.value:[],tags:targetMode.value==='tag'?selectedTags.value:[],ips:targetMode.value==='ip'?ipText.value.split(/[,\s]+/).map(value=>value.trim()).filter(Boolean):[],assetIds:[]}}
async function resolveTargets(){resolving.value=true;error.value='';message.value='';try{const result=await request<TargetResolve>('/api/v1/discovery/remote-targets/resolve',{method:'POST',body:JSON.stringify(selectorPayload())});resolvedTargets.value=result.targets;resolvedAssets.value=result.assets;message.value=`已匹配 ${result.assets.length} 台主机，去重后 ${result.targets.length} 个 IP`}catch(reason){resolvedTargets.value=[];resolvedAssets.value=[];error.value=reason instanceof Error?reason.message:'目标解析失败'}finally{resolving.value=false}}
async function submit(){busy.value=true;error.value='';message.value='';try{if(!resolvedTargets.value.length)await resolveTargets();if(!resolvedTargets.value.length)return;const execution=await request<Execution>('/api/v1/discovery/remote-executions',{method:'POST',body:JSON.stringify({operationId:commandMode.value==='preset'?operationId.value:'',command:commandMode.value==='custom'?customCommand.value:'',targets:resolvedTargets.value,port:port.value,credentialId:credentialId.value})});message.value=`${execution.id} 已提交，等待审批后执行`;await load()}catch(reason){error.value=reason instanceof Error?reason.message:'提交失败'}finally{busy.value=false}}
async function approve(id:string){busy.value=true;error.value='';try{await request(`/api/v1/discovery/remote-executions/${encodeURIComponent(id)}/approve`,{method:'POST'});message.value=`${id} 已审批并开始执行`;await load()}catch(reason){error.value=reason instanceof Error?reason.message:'审批失败'}finally{busy.value=false}}
function statusLabel(status:string){return {awaiting_approval:'待审批',running:'执行中',success:'成功',partial:'部分成功',failed:'失败'}[status]||status}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{load();timer=setInterval(()=>{if(executions.value.some(item=>item.status==='running'))load()},3000)});onBeforeUnmount(()=>{if(timer)clearInterval(timer)})
</script>

<template><section class="discovery-panel remote-execution"><header><div><h2>批量命令与远程执行</h2><span>支持预定义只读操作和受控自定义命令；所有执行均需审批并逐台记录 SSH 输出</span></div><button @click="load"><RefreshCw :class="{spin:busy}"/></button></header><div class="remote-safety"><ShieldCheck/><span><strong>安全边界</strong>：自定义命令自动标记为高风险，危险命令会被拦截，目标最多 20 台。</span></div><div class="remote-builder"><div class="remote-column"><h3>1. 选择执行内容</h3><div class="remote-mode"><button :class="{active:commandMode==='preset'}" @click="commandMode='preset'">预定义操作</button><button :class="{active:commandMode==='custom'}" @click="commandMode='custom'">自定义命令</button></div><label v-if="commandMode==='preset'"><span>只读操作</span><select v-model="operationId"><option v-for="operation in operations" :key="operation.id" :value="operation.id">{{operation.name}} · {{operation.description}}</option></select></label><label v-else><span>Shell 命令</span><textarea v-model="customCommand" rows="4" placeholder="例如：uptime && df -h"></textarea></label><div v-if="activeOperation" class="command-preview"><code>{{activeOperation.command}}</code><b :data-risk="activeOperation.risk">{{activeOperation.risk}}</b></div></div><div class="remote-column"><h3>2. 选择目标主机</h3><div class="remote-mode"><button :class="{active:targetMode==='projectGroup'}" @click="targetMode='projectGroup'">按项目组</button><button :class="{active:targetMode==='tag'}" @click="targetMode='tag'">按标签</button><button :class="{active:targetMode==='ip'}" @click="targetMode='ip'">按 IP/CIDR</button></div><label v-if="targetMode==='projectGroup'"><span>项目组（可多选）</span><select v-model="selectedGroups" multiple size="5"><option v-for="group in targetOptions.projectGroups" :key="group" :value="group">{{group}}</option></select></label><label v-else-if="targetMode==='tag'"><span>标签（可多选，任一命中即加入）</span><select v-model="selectedTags" multiple size="5"><option v-for="tag in targetOptions.tags" :key="tag" :value="tag">{{tag}}</option></select></label><label v-else><span>IP、CIDR 或主机名（逗号/换行分隔）</span><textarea v-model="ipText" rows="5" placeholder="172.28.69.161&#10;172.28.68.0/24"></textarea></label><button class="subtle" :disabled="resolving" @click="resolveTargets">{{resolving?'解析中':'解析匹配主机'}}</button></div><div class="remote-column"><h3>3. 连接参数</h3><label><span>SSH 端口</span><input v-model.number="port" type="number" min="1" max="65535"></label><label><span>SSH 凭据</span><select v-model="credentialId"><option value="">使用服务端默认</option><option v-for="credential in sshCredentials" :key="credential.id" :value="credential.id">{{credential.name}} ({{credential.username||'-'}})</option></select></label><div class="target-preview"><span>已解析目标 <b>{{resolvedTargets.length}}</b> 台</span><div v-if="resolvedAssets.length" class="target-assets"><span v-for="asset in resolvedAssets.slice(0,8)" :key="asset.id">{{asset.name}} · {{asset.ip}}</span><small v-if="resolvedAssets.length>8">还有 {{resolvedAssets.length-8}} 台...</small></div><small v-else>请选择范围后先解析目标</small></div><button class="primary" :disabled="busy||(!resolvedTargets.length&&(targetMode==='projectGroup'?selectedGroups.length===0:targetMode==='tag'?selectedTags.length===0:!ipText.trim()))" @click="submit">提交审批</button></div></div><div v-if="message" class="scanner-result">{{message}}</div><div v-if="error" class="discovery-error remote-error">{{error}}</div><div class="remote-history"><article v-for="execution in executions.slice(0,8)" :key="execution.id"><header><div><Terminal/><strong>{{execution.operationName}}</strong><span>{{execution.createdAt}} · {{execution.targets.length}} 台 · SSH {{execution.port}} · {{execution.requestedBy}}</span><code>{{execution.command}}</code></div><b :data-status="execution.status">{{statusLabel(execution.status)}}</b></header><div class="remote-targets"><span v-for="target in execution.targets" :key="target">{{target}}</span></div><div v-if="execution.status==='awaiting_approval'" class="remote-actions"><Clock3/><span>等待管理员审批</span><button class="primary" :disabled="busy" @click="approve(execution.id)">审批并执行</button></div><details v-else><summary>查看逐台执行结果</summary><div class="remote-results"><article v-for="result in execution.results" :key="result.target"><span><CheckCircle2 v-if="result.status==='success'"/><XCircle v-else/><b>{{result.target}}</b><small>{{result.duration||statusLabel(result.status)}}</small></span><pre v-if="result.output">{{result.output}}</pre><p v-if="result.error">{{result.error}}</p></article></div></details></article><div v-if="!executions.length" class="remote-empty">暂无远程执行记录</div></div></section></template>

<style scoped>
.remote-safety{display:flex;align-items:center;gap:10px;margin:0 20px 16px;padding:12px 14px;border:1px solid #155e75;border-radius:10px;background:#082b38;color:#a5f3fc}.remote-safety svg{flex:none}.remote-builder{display:grid;grid-template-columns:1.1fr 1.2fr 1fr;gap:12px;padding:0 20px 18px}.remote-column{display:grid;gap:10px;align-content:start;padding:14px;border:1px solid #18384a;border-radius:12px;background:#081a27}.remote-column h3{margin:0;color:#cae8f7;font-size:13px}.remote-column label{display:grid;gap:6px;color:#7894a8;font-size:11px}.remote-column select,.remote-column textarea,.remote-column input{width:100%;box-sizing:border-box;border:1px solid #22465f;background:#061725;color:#dcecff;padding:9px;outline:none}.remote-mode{display:flex;gap:5px}.remote-mode button{flex:1;padding:6px;font-size:11px}.remote-mode button.active{border-color:#22d3ee;color:#67e8f9}.command-preview{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px;background:#0d2a3b}.command-preview code{max-width:80%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#7dd3fc}.command-preview b{font-size:10px;color:#f59e0b}.target-preview{display:grid;gap:6px;padding:10px;background:#0d2a3b;color:#8fb3c7;font-size:11px}.target-assets{display:flex;flex-wrap:wrap;gap:5px}.target-assets span{padding:3px 6px;background:#12364b;color:#a5e8ff;font-size:10px}.remote-error{margin:0 20px 14px}.remote-history{display:grid;gap:12px;padding:0 20px 20px}.remote-history>article{border:1px solid #18384a;border-radius:12px;background:#081a27;overflow:hidden}.remote-history>article>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 15px;border-bottom:1px solid #123043}.remote-history>article>header>div{display:grid;grid-template-columns:auto 1fr;gap:2px 9px;align-items:center}.remote-history>article>header svg{grid-row:1/4;color:#22d3ee}.remote-history>article>header span{color:#6f91a5;font-size:12px}.remote-history>article>header code{grid-column:2;max-width:780px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#7dd3fc;font-size:10px}.remote-history b{font-size:12px}.remote-history b[data-status=awaiting_approval]{color:#f59e0b}.remote-history b[data-status=running]{color:#38bdf8}.remote-history b[data-status=success]{color:#2dd4bf}.remote-history b[data-status=partial]{color:#f59e0b}.remote-history b[data-status=failed]{color:#fb7185}.remote-targets{display:flex;flex-wrap:wrap;gap:6px;padding:11px 15px}.remote-targets span{padding:4px 8px;border-radius:6px;background:#0d2a3b;color:#9bdffc;font-family:monospace;font-size:12px}.remote-actions{display:flex;align-items:center;gap:9px;padding:0 15px 14px;color:#f59e0b}.remote-actions button{margin-left:auto}.remote-history details summary{cursor:pointer;padding:11px 15px;border-top:1px solid #123043;color:#7dd3fc}.remote-results{padding:0 15px 15px}.remote-results>article{padding:10px 0;border-top:1px solid #123043}.remote-results>article>span{display:flex;align-items:center;gap:7px}.remote-results small{color:#6f91a5}.remote-results pre{white-space:pre-wrap;margin:8px 0 0;padding:10px;border-radius:8px;background:#020b12;color:#bae6fd;max-height:240px;overflow:auto}.remote-results p{color:#fda4af;margin:8px 0 0}.remote-empty{text-align:center;color:#64869a;padding:30px}@media(max-width:1200px){.remote-builder{grid-template-columns:1fr}}
</style>